import{_ as d,o as e,c as r,ag as o}from"./chunks/framework.BoXUJ6sC.js";const u=JSON.parse('{"title":"도메인별 만들 것 — API · 이벤트","description":"","frontmatter":{},"headers":[],"relativePath":"planning/deliverables.md","filePath":"planning/deliverables.md"}'),a={name:"planning/deliverables.md"};function c(n,t,h,i,l,s){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="도메인별-만들-것-—-api-·-이벤트" tabindex="-1">도메인별 만들 것 — API · 이벤트 <a class="header-anchor" href="#도메인별-만들-것-—-api-·-이벤트" aria-label="Permalink to &quot;도메인별 만들 것 — API · 이벤트&quot;">​</a></h1><p><strong>지금 있는 API는 <a href="./../api/">API 목록</a>에 도메인별로 있습니다.</strong> 아래 표에는 아직 만들지 않았거나 만들지 않기로 한 API와 이벤트만 남깁니다 (앞의 <code>/api/v1</code> 생략). <code>단계</code> 열: ①~⑦ = 정상 흐름에 필요한 카드 · <strong>보완</strong> = 정상 흐름 다음 · <strong>최종</strong> = 최종 프로젝트(완료 · 진행 중 · 예정을 설명에 적음) · &quot;만들지 않음&quot; · &quot;세미 제외&quot; · &quot;최종&quot; 줄을 빼면 이 장의 API는 모두 구현되어 있습니다</p><p>v2.0: 이벤트는 모두 Kafka로 갑니다. 토픽은 <code>kidly.{보내는 도메인}.events</code>이고(3.3), 받는 쪽은 구독 그룹 <code>kidly.{받는 도메인}</code>으로 받습니다.</p><h3 id="이벤트-한눈에-보기" tabindex="-1">이벤트 한눈에 보기 <a class="header-anchor" href="#이벤트-한눈에-보기" aria-label="Permalink to &quot;이벤트 한눈에 보기&quot;">​</a></h3><table tabindex="0"><thead><tr><th>이벤트</th><th>보내는 쪽 → 받는 쪽</th><th>받는 쪽이 하는 일</th><th><code>data</code> 핵심 필드</th><th>단계</th></tr></thead><tbody><tr><td><code>member.registered</code> 회원가입됨</td><td>회원 → 결제 · 알림</td><td>지갑 생성 · 환영 메일</td><td>memberId · email</td><td>①</td></tr><tr><td><code>member.changed</code> 회원 정보 변경됨</td><td>회원 → 판매자</td><td>신청자 닉네임 반영</td><td>memberId · nickname</td><td>보완</td></tr><tr><td><code>member.withdrawn</code> 회원탈퇴됨</td><td>회원 → 회원(배송지) · 자녀 프로필 · <strong>결제</strong> (추천 · 커뮤니티 예정)</td><td>배송지 · 자녀 프로필 삭제 · <strong>지갑 동결</strong> / 활동 기록 · AI 응답 삭제(추천, P16) · 찜 삭제 · 리뷰 작성자 표시(커뮤니티, #663)</td><td>memberId</td><td>보완 · 최종</td></tr><tr><td><code>child.changed</code> 자녀 정보 변경됨</td><td>자녀 프로필 → 추천 · 주문</td><td>복사본 저장 (삭제면 삭제 직전 값 + deleted)</td><td>childId · memberId · heightCm · weightKg · gender · birthDate · bodyType(없으면 null) · preferredFit(없으면 null) · deleted</td><td>①</td></tr><tr><td><code>seller.changed</code> 판매자 정보 변경됨</td><td>판매자 → 회원 · 상품 · 주문 · 추천 · <strong>검색</strong></td><td>복사본 저장 (승인 · 정지 때 발행) · 상호명 색인(검색)</td><td>sellerId · businessName · status(ACTIVE · SUSPENDED)</td><td>② · 최종</td></tr><tr><td><code>product.changed</code> 상품 정보 변경됨</td><td>상품 → 추천 · 주문 · <strong>검색 · 커뮤니티</strong> · 상품(검색용 표, 되돌리기용)</td><td>복사본 저장 (판매 상태 변경 · 수정 · 품절 변경 때 발행) · 색인(검색) · 임베딩 다시 생성(추천)</td><td>productId · sellerId · name · categoryId · status · thumbnailUrl · createdAt · sizeFree · infoValues · options(optionId · optionName · size · price · minHeightCm · maxHeightCm · soldOut · saleStatus · values) · <strong>brand · description · sizeSpecs</strong>(#610)</td><td>② · 최종</td></tr><tr><td><code>order.created</code> 주문 생성됨</td><td>주문 → 상품</td><td>재고 차감 (선점)</td><td>orderId · memberId · items(orderItemId · optionId · quantity)</td><td>④</td></tr><tr><td><code>stock.deducted</code> 재고 차감됨</td><td>상품 → 주문</td><td>결제 요청 (결제대기일 때만)</td><td>orderId</td><td>④</td></tr><tr><td><code>order.payment-requested</code> 결제 요청됨</td><td>주문 → 결제</td><td>예치금으로 결제</td><td>orderId · memberId · amount · items(orderItemId · amount)</td><td>④</td></tr><tr><td><code>payment.completed</code> 결제 완료됨</td><td>결제 → 주문</td><td>주문 PAID · 판매자별 배송 생성</td><td>paymentId · orderId · amount · memberId · items(orderItemId · amount) · paidAt</td><td>④</td></tr><tr><td><code>order-item.purchase-confirmed</code> 구매확정됨</td><td>주문 → 정산 · 추천 · <strong>커뮤니티</strong></td><td>정산 대상 등록 / 구매 기록 저장 (자녀 · 사이즈가 있을 때만) / 리뷰 작성 자격</td><td>orderItemId · orderId · memberId · sellerId · childId · productId · optionId · size(사이즈 없는 상품은 null) · quantity · amount(단가 × 수량) · confirmedAt</td><td>⑥ · 최종</td></tr><tr><td><code>settlement.payout-requested</code> 정산 지급 요청됨</td><td>정산 → 결제</td><td>판매자 지갑 입금 (계산 완료 = 지급 요청)</td><td>settlementId · sellerId · amount · periodStartOn · periodEndOn</td><td>⑦</td></tr><tr><td><code>payment.payout-completed</code> 지급 완료됨</td><td>결제 → 정산</td><td>정산서 PAID</td><td>settlementId · sellerId · amount · ledgerId(0원이면 null) · paidAt</td><td>⑦</td></tr><tr><td><code>payment.payout-failed</code> 지급 실패함</td><td>결제 → 정산</td><td>정산서 FAILED</td><td>settlementId · sellerId · amount · reasonCode · failedAt</td><td>보완</td></tr><tr><td><code>stock.deduction-failed</code> 재고 부족함</td><td>상품 → 주문</td><td>주문 취소</td><td>orderId · reason · failures(orderItemId · reason) — reason: OUT_OF_STOCK · PRODUCT_NOT_ON_SALE · OPTION_NOT_ON_SALE</td><td>보완</td></tr><tr><td><code>payment.failed</code> 결제 실패됨</td><td>결제 → 주문</td><td>주문 취소</td><td>paymentId(금액 불일치면 null) · orderId · memberId · requestedAmount · reasonCode(INSUFFICIENT_BALANCE · AMOUNT_MISMATCH) · failedAt</td><td>보완</td></tr><tr><td><code>order.cancelled</code> 주문 취소됨</td><td>주문 → 상품 · 결제 (추천 예정)</td><td>재고 복구 / 결제됐으면 남은 금액 환불, 아직이면 이후 결제 요청 거절 / 구매자 취소면 활동 기록(추천)</td><td>orderId · memberId · reason(OUT_OF_STOCK · PAYMENT_FAILED · PAYMENT_EXPIRED · BUYER_CANCELLED) · items(orderItemId · optionId · quantity)</td><td>보완</td></tr><tr><td>order-item.cancelled 판매자 주문상품 취소됨</td><td>주문 → 결제 · 상품</td><td>주문상품 금액만큼 환불 / 재고 복구</td><td>orderId · memberId · sellerId · cancellationId · reason(OUT_OF_STOCK · WRONG_PRODUCT_INFO · OTHER) · items(orderItemId · optionId · quantity · amount)</td><td>최종</td></tr><tr><td>payment.refunded 환불 완료됨 (계약만)</td><td>결제 → 주문 · 정산</td><td>취소 완료 / 미정산 대상 제외 (K18)</td><td>refundId · paymentId · orderId · cancellationId · items(orderItemId · amount) · amount · refundedAt</td><td>최종</td></tr><tr><td>cart.item-added 장바구니 담김(발행은 이미 있음)</td><td>주문 → 추천</td><td>활동 기록 저장, 선호 점수 갱신</td><td>cartItemId · memberId · childId · productId · optionId · quantity · cartQuantity</td><td>최종</td></tr><tr><td>cart.item-removed 장바구니 빠짐(발행 요청)</td><td>주문 → 추천</td><td>활동 기록 저장, 선호 점수 갱신</td><td>cartItemId · memberId · childId · productId · optionId · quantity · cartQuantity</td><td>최종</td></tr><tr><td>search.performed 검색어 기록됨(발행은 이미 있음)</td><td>검색 → 추천</td><td>활동 기록 저장</td><td>memberId · keyword · categoryId · attributeValueIds · resultCount</td><td>최종</td></tr><tr><td>child.reference-garment.changed 기준 옷 변경됨</td><td>자녀 프로필 → 추천</td><td>기준 옷 복사본 저장</td><td>childId · part(TOP · BOTTOM) · lengthCm · widthCm · sourceOrderItemId</td><td>최종(2순위)</td></tr><tr><td><code>member.tokens-revoked</code> 토큰 무효화됨</td><td>회원 → API Gateway</td><td>무효화 목록에 넣어 그 회원의 기존 토큰 거절 (도메인 아님)</td><td>memberId · 무효화 시각</td><td>최종</td></tr><tr><td><code>wish.item-added</code> · <code>wish.sent</code> · <code>wish.approved</code> · <code>wish.rejected</code> 조르기</td><td>주문 → (추천 · 알림 예정)</td><td>활동 신호 · 인앱 알림</td><td>키 = 자녀 프로필 ID</td><td>최종(예정)</td></tr><tr><td><code>review.created</code> 리뷰 작성됨</td><td>커뮤니티 → (미정)</td><td>추천 · 검색 신호 (K28)</td><td>리뷰 ID · 상품 ID · 주문상품 ID · 회원 ID · 별점 · 작성 시각(본문 · 닉네임 제외)</td><td>최종(보류)</td></tr></tbody></table><p>이벤트 형식 · 보내고 받는 법은 6.2.</p><h2 id="회원-·-maruhxn" tabindex="-1">회원 · maruhxn <a class="header-anchor" href="#회원-·-maruhxn" aria-label="Permalink to &quot;회원 · maruhxn&quot;">​</a></h2><p>코드는 member(회원 · 배송지 · 인증) · childprofile(자녀 프로필) · seller(판매자) · notification(알림) 모듈로 나뉩니다.</p><table tabindex="0"><thead><tr><th>단계</th><th>API</th><th>설명</th></tr></thead><tbody><tr><td>보완</td><td><code>POST /admin/members/{memberId}/grant-admin</code> · <code>/revoke-admin</code></td><td>관리자 권한 부여 · 회수</td></tr><tr><td>만들지 않음</td><td><code>PUT /seller/payout-account</code></td><td>정산계좌 등록 · 변경 — 정산계좌 없음 (4장)</td></tr></tbody></table><table tabindex="0"><thead><tr><th>구분</th><th>내용</th></tr></thead><tbody><tr><td>보내는 이벤트</td><td>member.registered (①) · member.changed (보완) · member.withdrawn (보완) · child.changed (①, 자녀 프로필) · seller.changed (②, 판매자)</td></tr><tr><td>받는 이벤트</td><td>member.withdrawn → 배송지 · 자녀 프로필 삭제 · seller.changed → 판매자 상태 복사본(토큰 역할 계산) · member.changed → 신청자 닉네임 · member.registered → 환영 메일(알림)</td></tr><tr><td>시간 작업</td><td>만료된 Refresh Token 정리 · 실패한 알림 메일 재발송 (1분마다)</td></tr></tbody></table><p>자녀 API(등록 · 목록 · 상세 · 수정 · 삭제)는 회원 담당입니다. 명세 v2의 추천 도메인 표시와 다르며, 이 문서를 따릅니다.</p><p>최종: 보내는 이벤트에 <code>member.tokens-revoked</code>(→ Gateway)가 더해졌고, 받는 이벤트는 모두 Kafka입니다. 인증은 auth 도메인으로 분리 중이며(#686, PR #717), 머지되면 무효화 이벤트가 <code>auth.tokens-revoked</code>(<code>kidly.auth.events</code>)로 바뀝니다. 기준 옷 API(2순위)는 ① 카드에 있습니다.</p><h2 id="상품-·-heojungseok" tabindex="-1">상품 · heojungseok <a class="header-anchor" href="#상품-·-heojungseok" aria-label="Permalink to &quot;상품 · heojungseok&quot;">​</a></h2><table tabindex="0"><thead><tr><th>구분</th><th>내용</th></tr></thead><tbody><tr><td>보내는 이벤트</td><td>product.changed (②) · stock.deducted (④) · stock.deduction-failed (보완)</td></tr><tr><td>받는 이벤트</td><td>order.created 재고 차감 (선점) (④) · order.cancelled 재고 복구 · 이후 차감 거절 (보완) · seller.changed 판매자 복사본 · product.changed 검색용 표 갱신 (되돌리기용)</td></tr><tr><td>최종</td><td>판매자 · 주문 이벤트를 Kafka로 받음(그룹 <code>kidly.product</code>, #692) · <code>order-item.cancelled</code> 재고 복구(#716) · <code>product.changed</code>에 brand · description · sizeSpecs 추가(#610) · 보내는 이벤트는 아웃박스</td></tr></tbody></table><h2 id="검색-·-codes-gy-새-표" tabindex="-1">검색 · codes-gy (새 표) <a class="header-anchor" href="#검색-·-codes-gy-새-표" aria-label="Permalink to &quot;검색 · codes-gy (새 표)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>구분</th><th>내용</th></tr></thead><tbody><tr><td>보내는 이벤트</td><td>search.performed (최종, <code>kidly.search.events</code>, 키 회원 ID)</td></tr><tr><td>받는 이벤트</td><td>product.changed 상품 문서 색인 · seller.changed 상호명 색인 (최종)</td></tr><tr><td>구독 그룹 · DLT</td><td><code>kidly.search</code>. <code>kidly.product.events.search.dlt</code> · <code>kidly.seller.events.search.dlt</code>. 읽기 시작 위치는 latest라 기존 상품은 처음 채우기로 넣음</td></tr><tr><td>실행</td><td>apps/search-service. dev만 켜짐: 검색 서비스는 t3.large compose(프로필 <code>search</code>), Elasticsearch는 t3.medium k3s(3.1). 모니터링은 앱과 나눈 job <code>kidly-search</code> · 로그 <code>service_name=kidly-search</code></td></tr></tbody></table><h2 id="추천-·-heojungseok" tabindex="-1">추천 · heojungseok <a class="header-anchor" href="#추천-·-heojungseok" aria-label="Permalink to &quot;추천 · heojungseok&quot;">​</a></h2><table tabindex="0"><thead><tr><th>단계</th><th>API</th><th>설명</th></tr></thead><tbody><tr><td>최종</td><td><code>GET /recommendations/companions?productId=&amp;childId=</code></td><td>함께 사면 좋은 상품 4개(카테고리 짝 규칙 → 벡터 후보 20개 → AI 선택)</td></tr><tr><td>최종</td><td><code>POST /recommendations/product-views</code></td><td>상품 상세 진입 기록</td></tr><tr><td>최종</td><td><code>/missions</code> · <code>/purchase-requests</code> …</td><td>미션 쇼핑(v1.1 그대로, Kids Mode에서 정함)</td></tr></tbody></table><table tabindex="0"><thead><tr><th>구분</th><th>내용</th></tr></thead><tbody><tr><td>보내는 이벤트</td><td>없음</td></tr><tr><td>받는 이벤트</td><td>child.changed · product.changed(보강 칸 포함) 복사본 저장과 임베딩 갱신 · seller.changed 판매자 복사본 · order-item.purchase-confirmed 구매 기록(자녀 · 사이즈가 있을 때만) · cart.item-added · cart.item-removed(발행 요청) · order.cancelled(reason이 <code>BUYER_CANCELLED</code>일 때만) 활동 기록과 선호 점수 갱신 · search.performed 활동 기록 · member.withdrawn 활동 기록 · AI 응답 삭제 · child.reference-garment.changed 기준 옷 복사본(2순위)</td></tr><tr><td>구독 그룹 · DLT</td><td><code>kidly.recommend</code>, 토픽마다 <code>{토픽}.recommend.dlt</code>, <code>occurredAt</code> 비교로 늦게 온 옛 이벤트 무시</td></tr></tbody></table><h2 id="주문-·-l2j92" tabindex="-1">주문 · L2J92 <a class="header-anchor" href="#주문-·-l2j92" aria-label="Permalink to &quot;주문 · L2J92&quot;">​</a></h2><table tabindex="0"><thead><tr><th>단계</th><th>API</th><th>설명</th></tr></thead><tbody><tr><td>만들지 않음</td><td><code>POST /orders/{orderId}/items/{orderItemId}/cancel</code></td><td>구매자 주문상품 취소 (구매자 부분 취소 없음. 판매자 취소는 아래)</td></tr></tbody></table><table tabindex="0"><thead><tr><th>구분</th><th>내용</th></tr></thead><tbody><tr><td>보내는 이벤트</td><td>order.created (④) · order.payment-requested (④) · order-item.purchase-confirmed (⑥) · order.cancelled (보완, 구매자 취소 포함)</td></tr><tr><td>받는 이벤트</td><td>child.changed · product.changed 복사본 저장 (④) · stock.deducted (④) · payment.completed (④) · stock.deduction-failed · payment.failed · seller.changed 판매자 복사본 (보완)</td></tr><tr><td>시간 작업</td><td>자동 구매확정 (⑥, 10분마다) · 결제 제한 시간 만료 (보완, 1분마다)</td></tr><tr><td>보내는 이벤트 (최종)</td><td><code>cart.item-added</code> · <code>order-item.cancelled</code>(스위치) — 모두 아웃박스로 <code>kidly.order.events</code>. 예정: <code>cart.item-removed</code> · <code>wish.item-added</code> · <code>wish.sent</code> · <code>wish.approved</code> · <code>wish.rejected</code></td></tr><tr><td>받는 이벤트 (최종)</td><td>상품 · 판매자 · 자녀 프로필 · 결제 토픽을 모두 Kafka로(그룹 <code>kidly.order</code>). 실패는 <code>{토픽}.order.dlt</code>, 관리자가 DLT를 확인 · 재처리 · 종료</td></tr><tr><td>시간 작업 (최종)</td><td>택배 조회 자동 배송 완료 · 아웃박스 릴레이. 주기 작업은 한 서버에서만(advisory lock)</td></tr><tr><td>외부 연동 (최종)</td><td>Delivery Tracker (인증값이 없으면 기능만 꺼짐). 서킷브레이커(Resilience4j)는 예정(#708)</td></tr></tbody></table><h2 id="결제-·-codes-gy" tabindex="-1">결제 · codes-gy <a class="header-anchor" href="#결제-·-codes-gy" aria-label="Permalink to &quot;결제 · codes-gy&quot;">​</a></h2><table tabindex="0"><thead><tr><th>구분</th><th>내용</th></tr></thead><tbody><tr><td>보내는 이벤트</td><td>payment.completed (④) · payment.failed (보완) · payment.payout-completed (⑦) · payment.payout-failed (보완) — 모두 아웃박스로 <code>kidly.payment.events</code>에. payment.refunded는 계약만 있음(K18)</td></tr><tr><td>받는 이벤트</td><td>member.registered 지갑 생성 (①) · <strong>member.withdrawn 지갑 동결 (최종)</strong> · order.payment-requested 예치금 결제 (④) · order.cancelled 환불 · 이후 결제 요청 거절 (보완) · settlement.payout-requested 판매자 입금 (⑦) · <strong>order-item.cancelled 부분 환불 (최종, #711 · Kafka만)</strong></td></tr><tr><td>구독 그룹 · DLT</td><td><code>kidly.payment</code>. <code>kidly.member.events.payment.dlt</code> · <code>kidly.order.events.payment.dlt</code> · <code>kidly.settlement.events.payment.dlt</code>. 받는 종류는 헤더 eventType으로 고르고 그 밖의 종류는 건너뜀</td></tr><tr><td>시간 작업</td><td>충전 정리 (1분마다) · 주문 취소 환불 재처리 (1분마다) · <strong>아웃박스 릴레이 (1초마다)</strong> · <strong>보낸 아웃박스 정리 (매일 4시)</strong></td></tr><tr><td>외부 연동</td><td>토스페이먼츠 (충전 승인 · 취소 · 조회 · 웹훅). 연결 3초 · 읽기 30초 제한</td></tr></tbody></table><h2 id="정산-·-baiees" tabindex="-1">정산 · baiees <a class="header-anchor" href="#정산-·-baiees" aria-label="Permalink to &quot;정산 · baiees&quot;">​</a></h2><table tabindex="0"><thead><tr><th>구분</th><th>내용</th></tr></thead><tbody><tr><td>보내는 이벤트</td><td><code>settlement.payout-requested</code> (⑦)</td></tr><tr><td>받는 이벤트</td><td><code>order-item.purchase-confirmed</code> 정산 대상 등록 (⑥) · <code>payment.payout-completed</code> · <code>payment.payout-failed</code> 지급 결과 반영 (⑦)</td></tr><tr><td>시간 작업</td><td>영업일 일정산 — Spring Batch <code>settlementJob</code>, 영업일 09:05~17:05 매시간 시도 · 하루 1회 (⑦)</td></tr></tbody></table><h2 id="공통-·-팀" tabindex="-1">공통 · 팀 <a class="header-anchor" href="#공통-·-팀" aria-label="Permalink to &quot;공통 · 팀&quot;">​</a></h2><table tabindex="0"><thead><tr><th>단계</th><th>API</th><th>설명</th></tr></thead><tbody><tr><td>운영</td><td><code>/actuator/health</code> · <code>/actuator/prometheus</code></td><td>상태 확인 · 메트릭 수집 (밖에서는 Nginx가 막음)</td></tr><tr><td>최종</td><td><code>apps/gateway</code></td><td>서비스 API가 아님. 경로별 라우팅 · 토큰 검증 · 역할 검사 · CORS · 보안 응답 헤더, 정규화되지 않은 경로는 400</td></tr></tbody></table><h2 id="커뮤니티-·-l2j92" tabindex="-1">커뮤니티 · L2J92 <a class="header-anchor" href="#커뮤니티-·-l2j92" aria-label="Permalink to &quot;커뮤니티 · L2J92&quot;">​</a></h2><p>세미의 「리뷰 · 최종 프로젝트」를 대신합니다. 커뮤니티는 회원이 상품에 남기는 반응을 저장하고 보여 줍니다. 모듈 <code>domains/community</code>(컨텍스트 review · favorite), DB 스키마 <code>community</code>.</p><table tabindex="0"><thead><tr><th>ID</th><th>기능</th><th>이슈</th><th>상태(11/2)</th></tr></thead><tbody><tr><td>CM-01</td><td>커뮤니티 모듈 · 스키마 기본 구성</td><td>#657</td><td>머지</td></tr><tr><td>CM-02</td><td>상품 복사본 · 판매 상태 표시</td><td>#658</td><td>머지</td></tr><tr><td>CM-03</td><td>리뷰 작성 자격(구매확정 수신) · 작성 가능 목록</td><td>#659</td><td>머지</td></tr><tr><td>CM-04</td><td>리뷰 작성 · 수정 · 삭제, 상품별 집계</td><td>#660</td><td>머지</td></tr><tr><td>CM-05</td><td>상품별 리뷰 목록 · 내 리뷰 · 리뷰 요약</td><td>#661</td><td>머지</td></tr><tr><td>CM-06</td><td>찜 추가 · 취소 · 내 찜 목록 · 찜 수</td><td>#662</td><td>진행 중</td></tr><tr><td>CM-07</td><td>회원 탈퇴 반영</td><td>#663</td><td>예정</td></tr></tbody></table><table tabindex="0"><thead><tr><th>맡지 않는 일</th><th>담당 도메인</th></tr></thead><tbody><tr><td>구매확정 판단</td><td>주문</td></tr><tr><td>상품 원본 정보 · 상세 설명 · 이미지</td><td>상품</td></tr><tr><td>알림 발송</td><td>알림</td></tr><tr><td>리뷰 · 찜을 추천 신호로 쓸지</td><td>추천</td></tr><tr><td>검색 정렬(별점순 등)</td><td>검색</td></tr><tr><td>FAQ 자동 응답(챗봇)</td><td>미정 (별도 모듈 검토)</td></tr></tbody></table><table tabindex="0"><thead><tr><th>구분</th><th>내용</th></tr></thead><tbody><tr><td>보내는 이벤트</td><td>없음. <code>review.created</code>(<code>kidly.community.events</code>)는 받을 도메인이 정해지면 아웃박스로 (K28)</td></tr><tr><td>받는 이벤트</td><td><code>product.changed</code> 상품 복사본(더 늦게 발생한 것만) · <code>order-item.purchase-confirmed</code> 리뷰 작성 자격(주문상품마다 1건) · <code>member.withdrawn</code> 찜 삭제 · 리뷰 작성자 표시(예정)</td></tr><tr><td>구독 그룹 · DLT</td><td><code>kidly.community</code>, 실패는 1초 간격 3번 뒤 <code>{토픽}.community.dlt</code>(관리자 재처리 화면 없음). 수신 스위치 <code>kidly.community.kafka.consumer.enabled</code>(기본 켬)</td></tr></tbody></table>',33)])])}const b=d(a,[["render",c]]);export{u as __pageData,b as default};
